'use strict';
const DATA={"keys":["C","A","D","B","A"],"items":[{"id":"Q20-01","title":"Запитання Q20-01 — Де потрібна координація?","stem":"Умовна ситуація. Дві сусідні громади розглядають облаштування затіненого пішохідного маршруту до спільного транспортного вузла. Частини маршруту знаходяться на територіях різних громад. Регіональний перевізник може надати дані про користування вузлом. Європейська партнерська організація запропонувала лише методичну консультацію. Повноваження щодо конкретних ділянок і узгодження дій ще мають бути уточнені.","question":"Який підхід найкраще визначить потрібну міжрівневу співпрацю?","options":["A. Громади спочатку узгоджують власні відтинки маршруту, а контакт із перевізником планують після вибору місцевих рішень.","B. Регіонального перевізника залучають як координатора маршруту, а громади уточнюють лише місцеві обмеження на своїх територіях.","C. Громади узгоджують відповідальних за відтинки та спільний вузол, визначають роль перевізника і доцільність консультації партнера.","D. Громади одразу просять державну установу визначити спільні умови, щоб не витрачати час на окремі міжмуніципальні домовленості."],"feedback":"Q20-01 — Зворотний зв’язок після подання. Найкращий варіант C: дві громади пов’язують власні територіальні рішення зі спільним вузлом, визначають інформаційну роль перевізника та окремо оцінюють консультацію європейського партнера. A слушно починає з місцевих відтинків, але відкладає спільну транспортну залежність: було б доречніше, якби маршрут не мав спільного вузла. B використовує досвід перевізника, але без підтвердження надає йому координацію всіх ділянок; це могло б бути виправдано за окремим мандатом. D передбачає державний контакт до встановлення конкретної державної ролі; він доречний, якщо така залежність виявиться. Фактичні повноваження щодо ділянок ще потрібно уточнити."},{"id":"Q20-02","title":"Запитання Q20-02 — Хто ухвалює рішення, а хто допомагає?","stem":"Умовна ситуація. Муніципальна команда перевірила, що визначений місцевий орган уповноважений ухвалити остаточне рішення про зміну режиму користування громадським майданчиком. Приватна компанія може пояснити технічні обмеження; громадська організація пропонує зібрати позиції користувачів; міжнародний консультант ділиться методичним досвідом. Жодному з партнерів не передавали повноваження на остаточне рішення.","question":"Як найточніше організувати ролі учасників?","options":["A. Місцевий орган ухвалює рішення; компанія, громадська організація та консультант готують для нього різні види інформації.","B. Орган готує рішення разом із компанією та консультантом, а громадська організація підтверджує відповідність обраного варіанта потребам мешканців.","C. Компанія формує остаточний технічний варіант, орган перевіряє його допустимість, а громадська організація повідомляє про реакцію користувачів.","D. Орган залишає за собою рішення, але для швидкості отримує перед ним тільки технічну оцінку компанії, а інші відомості збирає пізніше."],"feedback":"Q20-02 — Зворотний зв’язок після подання. За умовою, повноваження визначеного місцевого органу ухвалити остаточне рішення перевірено. Варіант A розрізняє це повноваження, технічний внесок компанії, знання користувачів та методичну підтримку консультанта. B привабливий через спільну роботу, але ставить одну громадську організацію в роль підтверджувача потреб усіх; це вимагало б обґрунтованого представницького мандата та належної перевірки. C враховує технічну здійсненність, проте фактично надає компанії вирішальну роль, якої за умовою вона не має; іншим був би випадок формально визначеного повноваження. D зберігає формальне рішення за органом, але передчасно відсуває думку користувачів і методичну інформацію; він був би сильнішим, якби ці відомості вже отримали."},{"id":"Q20-03","title":"Запитання Q20-03 — Кого не вистачає в розмові?","stem":"Умовна ситуація. У громаді розглядають зміну годин доступу до прохолодного громадського приміщення під час літньої спеки. Представники сусідніх підприємств підтримують коротший вечірній режим, оскільки їм важливий порядок навколо будівлі; активна група денних відвідувачів підтримує наявний розклад. Потреби вечірніх працівників і маломобільних користувачів поки що не з’ясовували.","question":"Який підхід найкраще допоможе врахувати суперечливі інтереси?","options":["A. Опитати ширше коло денних відвідувачів і на основі переважної позиції визначити попередній розклад.","B. Попросити підприємства й денних відвідувачів погодити компромісні години, а незалучені групи повідомити про проєкт рішення.","C. Зібрати додаткові відгуки через уже активні групи і доручити їм стисло представити інтереси решти користувачів.","D. З'ясувати потреби вечірніх і маломобільних користувачів, потім зіставити вплив можливих годин доступу на різні групи."],"feedback":"Q20-03 — Зворотний зв’язок після подання. Варіант D прямо усуває найважливішу прогалину: невідомі потреби вечірніх та маломобільних користувачів, після чого дозволяє порівняти наслідки різних годин. A розширює опитування, але лише серед денних відвідувачів; підхід був би достатнішим, якби інші групи не залежали від режиму. B шукає компроміс серед присутніх, але повідомлення про проєкт не замінює вивчення потреб відсутніх. C залучає активістів як канали зворотного зв’язку, однак без перевірки не можна вважати їх представниками всіх; посередницька функція могла б допомогти разом із прямим залученням інших груп. Балансування не гарантує одностайності."},{"id":"Q20-04","title":"Запитання Q20-04 — Який крок можна обґрунтувати?","stem":"Умовна ситуація. Компетенцію міського органу щодо облаштування затіненого майданчика вже підтверджено. Є два попередні варіанти розташування навісу. Один швидше дає тінь, але може ускладнити доступ до сусіднього медичного закладу; інший зберігає звичний прохід, проте менш зручний для частини щоденних відвідувачів. Наслідки варіантів ще не порівняно з представниками закладу та користувачами.","question":"Який наступний управлінський крок найбільш обґрунтований?","options":["A. Вибрати швидший варіант як попередній пріоритет, а питання доступності перевірити під час підготовки його реалізації.","B. Порівняти з медичним закладом і користувачами наслідки обох варіантів, після чого подати мотивовану рекомендацію органу.","C. Спершу погодити з медичним закладом умови доступу, а оцінку зручності для решти відвідувачів провести після вибору місця.","D. Зібрати письмові позиції основних груп і віддати вибір розташування на їхнє голосування без додаткового порівняння впливів."],"feedback":"Q20-04 — Зворотний зв’язок після подання. Варіант B найкращий: компетенцію вже підтверджено, але потреби користувачів і наслідки для доступу до медичного закладу залишаються відкритими. Порівняння дає підставу для мотивованої рекомендації. A реагує на спеку, однак переносить важливу перевірку доступності на пізніший етап; за підтвердженої невідкладної небезпеки й оцінених наслідків швидкість могла б стати пріоритетом. C залучає заклад, але перевіряє тільки один інтерес і лише потім інших користувачів. D збирає ширші позиції, проте саме голосування без аналізу наслідків для доступу не визначає найкращий варіант. Це вибір для заданих фактів, не універсальна процедура."},{"id":"Q20-05","title":"Запитання Q20-05 — Що встановлено, а що лише припускають?","stem":"Умовна ситуація. У робочій записці про облаштування місця короткого перепочинку під час спеки є підтверджена інформація про те, хто відповідає за ділянку. У записці також сказано, що «всі мешканці підтримують рішення» на підставі двох листів і що міжнародний партнер «точно долучиться» на підставі неформальної розмови. Інших підтверджень команда не має.","question":"Яке формулювання варто використати для наступного управлінського обговорення?","options":["A. Подати відповідальність за ділянку як факт, а підтримку громади й участь партнера як неперевірені висновки, які слід уточнити.","B. Подати відповідальність за ділянку і два листи як перевірені факти, а участь партнера — як імовірну домовленість.","C. Подати підтверджену відповідальність як факт, а підтримку мешканців як основну робочу позицію до наступного опитування.","D. Подати відповідальність за ділянку й листи як факти, а усну розмову як достатню підставу планувати внесок партнера."],"feedback":"Q20-05 — Зворотний зв’язок після подання. Варіант A правильно зберігає підтверджену відповідальність як факт і відокремлює від неї два непідтверджені узагальнення: підтримку всіх мешканців та гарантовану участь партнера. B слушно розрізняє письмові й усні сигнали, але сам факт двох листів доводить лише наявність цих листів, а не широку підтримку; письмові докази представництва посилили б твердження. C також відокремлює відповідальність, але завищує значення листів без перевірки інших інтересів; він був би сильнішим після репрезентативного з’ясування позицій. D документує розмову, але помилково планує внесок як гарантований; потрібне підтвердження партнера. Жоден варіант не встановлює реальних правових або донорських зобов’язань."}],"names":["Початок","Управлінська проблема","Чотири рівні","Ролі учасників","Інтереси сторін","Управлінський вибір","Практичні ситуації","Джерела","Управлінська записка","Підсумок","Підсумкова перевірка","Завершення"],"portfolioTitle":"Управлінська записка про координацію та баланс інтересів для одного кліматичного рішення громади"};
const STORAGE_NS='ucan.l20.prerelease.v1.';
const G=(id)=>document.getElementById(id);
const pageEls=[...document.querySelectorAll('.page')];
const total=pageEls.length;
const copyCache={portfolio:undefined};
function msg(s){G('global-status').textContent=s;}
function save(k,v){try{localStorage.setItem(STORAGE_NS+k,JSON.stringify(v));return true}catch(err){return false}}
function read(k,d){try{let x=localStorage.getItem(STORAGE_NS+k);return x===null?d:JSON.parse(x)}catch(err){return d}}
// v1.0.2: deterministic one-time migration from numeric legacy progress.
// Preserve the existing separate portfolio storage key verbatim.
const SEMANTIC_PAGES=['page-intro','page-governance1','page-levels','page-roles','page-interests','page-decisions','page-practice','page-resources','page-note','page-reflection','page-assessment','page-complete'];
const OLD_PAGES=['page-intro','page-governance1','page-levels','page-roles','page-interests','page-decisions','page-practice','page-note','page-resources','page-reflection','page-assessment','page-complete'];
let restoredPage=0,restoreWarning='';
const schema=read('progress_schema',null);
if(schema===2){
 const semantic=read('page_id','page-intro');
 const found=SEMANTIC_PAGES.indexOf(semantic);
 if(found<0){restoreWarning='Збережений розділ не розпізнано. Навчання відкрито з початку.';restoredPage=0;}
 else restoredPage=found;
}else if(schema===null){
 const old=read('page',0);
 if(Number.isInteger(old)&&old>=0&&old<OLD_PAGES.length){restoredPage=SEMANTIC_PAGES.indexOf(OLD_PAGES[old]);}
 else {restoreWarning='Попередній прогрес не розпізнано. Навчання відкрито з початку.';restoredPage=0;}
}else{restoreWarning='Невідома версія прогресу. Навчання відкрито з початку; Ваша записка збережена.';restoredPage=0;}
save('progress_schema',2);save('page_id',SEMANTIC_PAGES[restoredPage]);
let page=restoredPage;
let complete=read('complete',false)===true;
let checked=false;
let attempts=Math.max(0,Number(read('attempts',0))||0);
let storageOK=save('init',{schema:1});
let portfolio=String(read('portfolio',''));
let shown=Array.isArray(read('revealed',[]))?read('revealed',[]):[];
const note=G('portfolio');note.value=portfolio;
let answers=Array.from({length:5},()=>null);

// UI20 v1.0.4: route overview is viewing position, never assessment achievement.
// This visited Set is deliberately session-only; original progress/storage schema stays intact.
const visitedPages=new Set();
const routeMap=G('l20-route-map'),routeList=G('route-map-list');
const routeButtons=SEMANTIC_PAGES.map((semantic,i)=>{
 const button=document.createElement('button');
 button.type='button';button.className='route-chip';button.dataset.pageId=semantic;
 const number=document.createElement('span');number.className='route-number';number.textContent=String(i+1);
 const label=document.createElement('span');label.className='route-name';label.textContent=DATA.names[i];
 const state=document.createElement('span');state.className='route-state';state.textContent='Попереду';
 button.append(number,label,state);
 button.addEventListener('click',()=>{if(i===total-1&&!complete)return;showPage(i);});
 routeList.append(button);return button;
});
function revealCurrentRoute(){
 const active=routeButtons[page];if(!active)return;
 // Scroll the strip itself only; scrollIntoView() could unexpectedly move the page.
 const left=active.offsetLeft-routeList.offsetLeft;
 const desired=Math.max(0,left-(routeMap.clientWidth-active.offsetWidth)/2);
 if(Math.abs(routeMap.scrollLeft-desired)>4)routeMap.scrollLeft=desired;
}
// F20-A11Y-02: merely focusing a chip must reveal its full outline INSIDE the strip.
// No route activation and no document scroll are performed here.
function revealFocusedRoute(button){
 const nav=routeMap.getBoundingClientRect(),chip=button.getBoundingClientRect(),pad=9;
 let delta=0;
 if(chip.left<nav.left+pad)delta=chip.left-nav.left-pad;
 else if(chip.right>nav.right-pad)delta=chip.right-nav.right+pad;
 if(Math.abs(delta)>1)routeMap.scrollTo({left:routeMap.scrollLeft+delta,behavior:'instant'});
}
routeButtons.forEach(button=>button.addEventListener('focus',()=>{
 revealFocusedRoute(button);
 requestAnimationFrame(()=>{if(document.activeElement===button)revealFocusedRoute(button);});
}));
function updateRouteMap(){
 routeButtons.forEach((button,i)=>{
  const current=i===page,locked=i===total-1&&!complete,visited=visitedPages.has(i)&&!current;
  const state=current?'Зараз':locked?'Закрито':visited?'Переглянуто':'Попереду';
  button.disabled=locked;button.classList.toggle('is-current',current);
  button.classList.toggle('is-visited',visited);button.classList.toggle('is-locked',locked);
  if(current)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');
  button.querySelector('.route-state').textContent=state;
  button.setAttribute('aria-label',`${i+1} із ${total}. ${DATA.names[i]}. ${state}${locked?', доступ після успішної перевірки':''}`);
 });
 requestAnimationFrame(revealCurrentRoute);
}
function showPage(to,{focus=true}={}){
 to=Math.max(0,Math.min(total-1,to));
 if(to===total-1&&!complete)return;
 page=to;pageEls.forEach((el,i)=>{el.hidden=i!==page;});
 const label=DATA.names[page]||'Навчання';G('page-label').textContent=label;
 const pct=Math.round((page+1)/total*100);
 G('page-count').textContent=`${page+1} / ${total}`;
 G('page-position').textContent=`${page+1} / ${total}`;
 G('progress-percent').textContent=`${pct}%`;
 G('progress-bar').style.width=`${pct}%`;
 G('progress-meter').setAttribute('aria-valuenow',String(pct));
 G('progress-meter').setAttribute('aria-valuetext',`Сторінка ${page+1} із ${total}, позиція у занятті ${pct} відсотків`);
 visitedPages.add(page);updateRouteMap();
 G('prev').disabled=page===0;
 G('next').disabled=page===total-1||(page===total-2&&!complete);
 G('next').textContent=page===total-2?'Перейти до завершення ➡️':'Наступний розділ ➡️';
 save('page',page);save('page_id',SEMANTIC_PAGES[page]);save('progress_schema',2);window.scrollTo({top:0,behavior:'instant'});
 if(focus){const h=pageEls[page].querySelector('h1,h2')||G('main');h.setAttribute('tabindex','-1');h.focus({preventScroll:true});}
}
G('prev').addEventListener('click',()=>showPage(page-1));
G('next').addEventListener('click',()=>showPage(page+1));
G('back-to-note').addEventListener('click',()=>showPage(8));

for(const n of [1,2]){
 const b=document.querySelector(`button[data-reveal="${n}"]`);
 const f=G(`formative-feedback-${n}`);
 function reveal(open){f.hidden=!open;b.setAttribute('aria-expanded',String(open));b.textContent=open?'Приховати пояснення':'Показати пояснення';}
 reveal(shown.includes(n));
 b.addEventListener('click',()=>{const will=f.hidden;reveal(will);shown=will?[...new Set([...shown,n])]:shown.filter(x=>x!==n);save('revealed',shown);if(will)msg('Пояснення до ситуації показано.');});
}

if(!storageOK){G('note-status').textContent='Цей браузер обмежує локальне збереження. Скопіюйте записку або завантажте PDF до закриття вкладки.';}
note.addEventListener('input',()=>{portfolio=note.value;copyCache.portfolio=portfolio;const ok=save('portfolio',portfolio);G('note-status').textContent=ok?'Чернетка збережена локально у цьому браузері.':'Локальне збереження недоступне. Зробіть власну копію.';});

